#!/bin/bash
# check_fd_usage.sh - file handles allocated across the whole kernel, as a percentage of the
# kernel maximum, from /proc/sys/fs/file-nr. Takes no process argument.
WARN=${1:-85}
CRIT=${2:-95}
read -r alloc _unused max < /proc/sys/fs/file-nr
pct=$(( alloc * 100 / max ))
if [ "$pct" -ge "$CRIT" ]; then echo "FD CRITICAL - ${pct}% of file handles allocated"; exit 2; fi
if [ "$pct" -ge "$WARN" ]; then echo "FD WARNING - ${pct}% of file handles allocated"; exit 1; fi
echo "FD OK - ${pct}% of file handles allocated"; exit 0

